import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { generateId } from "../../helpers/id.js";

// Music playlists (moods, actor themes, a vocal group) as a compendium pack both worlds import from. music.json is generated by
// dev/harness/music-build-playlists.py from docs/MUSIC-MOODS.md. Only paths into the shared Data/music folder are stored, never audio.
interface Snd { name: string; path: string; volume: number; repeat: boolean }
interface Def { name: string; mode: number; description: string; sounds: Snd[] }

const defs: Def[] = JSON.parse(readFileSync(join(dirname(fileURLToPath(import.meta.url)), "music.json"), "utf8"));
const stats = { coreVersion: "13", systemId: "dnd5e", systemVersion: "5.1.10" };

export default defs.map((d) => {
  const id = generateId(`playlist/${d.name}`);
  return {
    _id: id, name: d.name, description: d.description, channel: "music", mode: d.mode, sorting: "a", fade: 1000, folder: null, seed: null, playing: false, flags: {}, ownership: { default: 0 },
    sounds: d.sounds.map((s, i) => ({
      _id: generateId(`playlist/${d.name}/${i}/${s.path}`), name: s.name, description: "", path: s.path, channel: "", playing: false, pausedTime: null, repeat: s.repeat,
      volume: s.volume, fade: 1000, sort: i * 100000, flags: {}, _stats: stats,
    })),
    _stats: stats,
  };
});
